const POEMS = [
  "burnley boy, london girl — written in the stars",
  "met on azar, changed everything",
  "15th feb 2026 — the day it all began",
  "both norwegian souls chasing the northern lights",
  "she slept on top of me in the passenger seat 😭",
  "25th april — first time i saw her for real",
  "5 days in london — a trailer for forever",
  "myyyy girl yeah — myyyy man yeah",
  "distance means nothing when it's this real",
  "waking up next to you felt like home",
  "from azar messages to 5 days in london",
  "one day this is everyday — after marriage",
];

